    // "M x y", "L x y", "Q cx cy x y", "C x1 y1 x2 y2 x y", "Z", scaled from 64 points to the rect
    static func path(_ id: String, in r: CGRect) -> Path {
        var p = Path(); guard let d = paths[id == "switch2" ? "switch" : id] else { return p }
        let s = min(r.width, r.height) / 64, ox = r.midX - 32 * s, oy = r.midY - 32 * s
        var cmd: Character = "M", nums: [CGFloat] = [], cur = ""
        func pt(_ i: Int) -> CGPoint { CGPoint(x: ox + nums[i] * s, y: oy + nums[i + 1] * s) }
        func flush() {
            if !cur.isEmpty, let v = Double(cur) { nums.append(CGFloat(v)) }; cur = ""
        }
        func run() {
            flush()
            switch cmd {
            case "M" where nums.count >= 2: p.move(to: pt(0))
            case "L" where nums.count >= 2: p.addLine(to: pt(0))
            case "Q" where nums.count >= 4: p.addQuadCurve(to: pt(2), control: pt(0))
            case "C" where nums.count >= 6: p.addCurve(to: pt(4), control1: pt(0), control2: pt(2))
            case "Z": p.closeSubpath()
            default: break
            }
            nums = []
        }
        for ch in d {
            if "MLQCZ".contains(ch) { run(); cmd = ch }
            else if ch == " " { flush() }
            else if ch == "-" { flush(); cur = "-" }
            else { cur.append(ch) }
        }
        run(); return p
    }
}

struct ControllerShape: Shape { let id: String; func path(in r: CGRect) -> Path { ControllerArt.path(id, in: r) } }
